const concat = (...arrays) =&gt; {
    const total = arrays.reduce((n, a) =&gt; n + a.length, 0);
    const buf = new Uint8Array(total);
    let off = 0;
    for (const a of arrays) {
        buf.set(a, off);
        off += a.length;
    }
    return buf;
};

